#include "nori/core.hpp"
#include <iostream>
#include <thread>
using namespace nori;
int main(int argc,char**argv){if(argc<3)return 2;HttpClient c;std::atomic_bool no=false;HttpRequest r;r.url=std::string(argv[1])+"/health";r.ca_file=argv[2];r.retries=0;auto h=c.async(r);auto ok=h.get();if(ok.status!=200||!ok.error.empty()){std::cerr<<"valid TLS: "<<ok.status<<" "<<ok.error<<'\n';return 1;}r.ca_file="";auto bad=c.perform(r,no);if(bad.status||bad.error.find("TLS")==std::string::npos){std::cerr<<"untrusted certificate accepted\n";return 1;}r.ca_file=argv[2];r.url=std::string(argv[1]);auto pos=r.url.find("localhost");if(pos==std::string::npos)return 2;r.url.replace(pos,9,"127.0.0.1");r.url+="/health";auto hostname=c.perform(r,no);if(hostname.error.find("TLS")==std::string::npos){std::cerr<<"hostname mismatch accepted\n";return 1;}r.url=std::string(argv[1])+"/v2/device/access";auto absent=c.perform(r,no);if(absent.status!=401){std::cerr<<"v2 must reject anonymous: "<<absent.status<<'\n';return 1;}r.url="http://localhost/health";if(c.perform(r,no).error!="invalid request")return 1;r.url=std::string(argv[1])+"/slow";auto slow=c.async(r);std::this_thread::sleep_for(std::chrono::milliseconds(200));slow.cancel();auto stopped=slow.get();if(!stopped.cancelled){std::cerr<<"cancel failed\n";return 1;}std::cout<<"TLS, real backend, anonymous v2 rejection and cancellation passed\n";}
